#!/usr/bin/env bash
# Prepares the demo each time the Codespace starts.
set -e
cd /workspaces/ess-iv-crm
echo "Waiting for MySQL..."
for i in $(seq 1 90); do
  mysqladmin ping -h db -u ess4crm -pdemo-db-password --silent 2>/dev/null && break
  sleep 2
done
if [ ! -f config.php ]; then
  URL="http://localhost/"
  if [ -n "$CODESPACE_NAME" ]; then URL="https://${CODESPACE_NAME}-80.${GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN}/"; fi
  KEY=$(head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n')
  cat > config.php <<PHP
<?php
// Demo configuration for GitHub Codespaces (generated by .devcontainer/start.sh).
return [
    'db' => ['host' => 'db', 'port' => 3306, 'name' => 'ess4crm', 'user' => 'ess4crm', 'pass' => 'demo-db-password'],
    'timezone' => 'Africa/Johannesburg',
    'app_url' => '${URL}',
    'cron_key' => '${KEY}',
    'debug' => true,
    // All emails are caught by Mailpit (the "Demo mailbox" port); nothing is sent to the internet.
    'mail' => ['transport' => 'smtp', 'from' => 'crm@ess4-demo.local', 'from_name' => 'ESS IV CRM (demo)',
               'smtp_host' => 'mail', 'smtp_port' => 1025, 'smtp_secure' => '', 'smtp_user' => '', 'smtp_pass' => ''],
];
PHP
fi
php scripts/demo-setup.php
date -Iseconds > install.lock
echo "ESS IV CRM demo is running on port 80. Sign in with admin / Demo-Admin-2026."
